import sys

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def can_move(x1, y1, x2, y2):
    if x1 == x2 and y1 == y2:
        return False
    if x1 == 0 or x2 == 0 or y1 == 0 or y2 == 0:
        return False
    g1 = gcd(x1, y1)
    g2 = gcd(x2, y2)
    x1 //= g1
    y1 //= g1
    x2 //= g2
    y2 //= g2
    return gcd(x1 + x2, y1 + y2) == 1

def main():
    input = sys.stdin.readline
    n = int(input())
    points = []
    for _ in range(n):
        a, b, c, d = map(int, input().split())
        x = a // b
        y = c // d
        points.append((x, y))

    moves = []
    used = [False] * n

    for i in range(n):
        if used[i]:
            continue
        for j in range(i + 1, n):
            if used[j]:
                continue
            if can_move(points[i][0], points[i][1], points[j][0], points[j][1]):
                moves.append((i + 1, j + 1))
                used[i] = True
                used[j] = True
                break

    print(len(moves))
    for move in moves:
        print(*move)

if __name__ == "__main__":
    main()
